const MapChile = ({ element, active, highlighted, width, onClick, onChange }) => {
  return (
    <ElementWrapper
      element={element}
      onClick={onClick}
      onChange={onChange}
      maxWidth={width}
      active={active}
      highlighted={highlighted}
      resizeHandles={['e']}
      editable
      fit
    >
      <MapChileContent element={element} />
    </ElementWrapper>
  );
};

export const MapChilePresent = ({ element }) => {
  return <MapChileContent element={element} />;
};

export const MapChilePreview = () => {
  return <MapChileContent element={{ config: { data: [], fill: '#f9fafb', stroke: '#f9fafb' } }} />;
};

